// Display dates as DD-MM-YYYY (Indian convention). Internally everything
// still stores/sorts as YYYY-MM-DD — this only changes what's shown.
const fmtDate = v => {
  if (!v || !/^\d{4}-\d{2}-\d{2}/.test(v)) return v || '—';
  const [y, m, d] = v.slice(0, 10).split('-');
  return `${d}-${m}-${y}`;
};

