const todayStr = () => new Date().toISOString().slice(0,10);

// Auto invoice numbering: PS + YYYY + MM + running count within that month
// (not the date) — e.g. "PS20260701" is the 1st invoice made in July 2026.
// Lets you tell how many invoices were raised in a given month just from
// the number itself.
function generateNextInvoiceNo() {
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const prefix = `PS${yyyy}${mm}`;
  const existing = Store.all('invoices')
    .map(inv => inv.number)
    .filter(no => typeof no === 'string' && no.startsWith(prefix));
  let maxSeq = 0;
  existing.forEach(no => {
    const seqPart = no.slice(prefix.length);
    const seqNum = parseInt(seqPart, 10);
    if (!isNaN(seqNum) && seqNum > maxSeq) maxSeq = seqNum;
  });
  const nextSeq = String(maxSeq + 1).padStart(2, '0');
  return `${prefix}${nextSeq}`;
}

// SHA-256 hex digest via the browser's built-in Web Crypto API.
// Used only for the Google Sheets sync token (Settings → Sync with
// Google Sheets) — nothing to do with login, which is Supabase Auth.
async function sha256Hex(text) {
  const enc = new TextEncoder().encode(text);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

/* ---------- Module configs: drives generic table + form rendering ---------- */
function invoicePaidSoFar(invoiceId) {
  return Store.all('payments')
    .filter(p => p.invoiceId === invoiceId)
    .reduce((s, p) => s + Number(p.amount || 0), 0);
}
